# Q11: update /output/report.json with the cross-team wing checks (s69, s70).  Re-runnable: removes its own earlier entries (evidence tag 'Q11').
import json,shutil
R='/output/report.json'; shutil.copy(R,'/workspace/out/report_before_q11.json'); r=json.load(open(R))
res=[x for x in r['results'] if not x.get('evidence','').startswith('Q11:')]
r['recipe']=[x for x in r['recipe'] if 'Q11' not in x.get('description','')]
r['caveats']=[c for c in r['caveats'] if not c.startswith('Q11:')]
for x in res:
    if x['quantity'].startswith('HCN/HCO+ 3-2 ratio in the blue-wing blob (Sblue') and 'Q11' not in x['value']:
        x['value']+=' [Q11 UPDATE: in a fixed 2" aperture with local-centroid velocities R_wing(Xb4d)=1.3-1.4 but 0.91 (0.63-1.3) in Xb4b smoothed to 1.05" (HCN wing flux recovered 61% vs HCO+ 92%); the HCN excess over k*HCO+ is 4.6 sigma in Xb4d and 0.8 sigma in Xb4b, so R_wing>R_core is array dependent, not robust; see the Q11 entries]'
A=lambda n,v:{'name':n,'value':v}
com=[A('distance','40 Mpc (1" = 194 pc)'),A('systemic velocity','VSYS 2780 km/s radio-LSRK (s3b); local centroid = Gaussian centroid of HCO+ 3-2 in the aperture (+-250 km/s)'),
 A('data','pbcor cubes Xb4d spw27 (HCN) / spw25 (HCO+) and Xb4b spw27/spw25; Xb4d at native 0.94x0.74" and convolved to a 1.05" circular beam; Xb4b at 0.25" native, 0.30" and 1.05" (Fourier convolution, flux rescaled by beam-area ratio, s30 loader); aperture r=1.0" (2" diameter) unless stated'),
 A('baseline','per-pixel median of -900<v-VSYS<-450 km/s (variant B: linear fit incl. 480..700; variant C: median v<-800 is biased at N because the HCO+ baseline at N sits ~-1 mJy/beam below zero for -900..-200 km/s: C gives N blue-half HCO+ ~0, rejected)'),
 A('noise','empirical: scatter of the same window and aperture at 60 random line-free positions 5-9.5" from the N-S midpoint (bright emission masked), paired HCN/HCO+ draws; includes baseline and sidelobe scatter; no extra 10% floor unless stated'),
 A('ratio convention','R_Tb = (integrated Jy km/s HCN / HCO+)*(nu_HCO+/nu_HCN)^2 = *1.0126; blue half = v_loc-400..-100 km/s')]
def add(q,t,v,u,un,conf,ev,extra=()):
    res.append(dict(quantity=q,target=t,value=v,uncertainty=u,unit=un,assumptions=com+list(extra),confidence=conf,evidence='Q11: '+ev))
add('Blue-half (v_loc-400..-100 km/s) HCN/HCO+ 3-2 Tb ratio in a fixed 2" aperture at Soutflow (S+(-0.2",-1.85")), N, Bridge, S: reproduction of team-a p0006/p0005-r01 in Xb4d and Xb4b@1.05"',
 'Soutflow, N, Bridge, S',
 'Xb4d@1.05" (baseline A): Soutflow 1.36 [68%: 1.13,1.66] (HCN 0.630+-0.063 = 10 sigma, HCO+ 0.468+-0.080 = 5.9 sigma Jy km/s; local centroid -29 km/s); native Xb4d 1.30 [1.09,1.58]; Xb4b smoothed to 1.05": 0.91 [0.63,1.32] (HCN 0.387+-0.081, HCO+ 0.429+-0.098). Baseline B: 1.34/1.34/0.91. Team-a: 1.24 (1.18-1.30) and 1.00. Core (|v_loc|<100) at Soutflow 0.48-0.50 (noise inflated by extended emission, +-0.2). N: 0.83 [0.48,1.17] (Xb4d@1.05"), 0.92 native, 0.65 [0.47,0.84] (Xb4b), vs N core 0.73-0.74: no significant blue-half rise at N (team-a 1.13 within 1 sigma). Bridge: blue half NOT detected (HCN 1.1 sigma, HCO+ 1.6 sigma; ratio unconstrained [0.23-2.5]); team-a Bridge 1.32 is not reproduced as a detection; the red half of Bridge is 1.47 (HCN 6 sigma, HCO+ 2 sigma). S: 0.61 [0.34,0.80] (Xb4d@1.05"), 0.49 native, 0.49 (Xb4b), vs S core 0.366 (HCN 3.8 sigma, HCO+ 5 sigma in the wing). Differences, blue half (paired draws, Xb4d@1.05"; Xb4b in brackets): Soutflow-N +0.53 [+0.10,+0.94] P(>)=0.88 (Xb4b +0.27, 0.81); Soutflow-Bridge +0.75 [-0.14,+1.24] (Bridge undetected); Soutflow-S +0.76 [+0.43,+1.11] P=0.98, z=2.0 with a 10% floor (Xb4b +0.42, P=0.87, z=1.0). Verdict: team-a p0006 (i) holds: Soutflow R>S and R>S core, but is not distinguishable from N (and the Bridge blue half is not measured); the 1.0-1.4 range is the array dependence, 1.3-1.4 in Xb4d versus 0.9 in Xb4b. Blue-half fluxes at N differ between Xb4b and Xb4d by 0.15-0.3 Jy km/s (N core is 10x brighter: sidelobe/dynamic-range floor), comparable to the Soutflow wing flux, so any wing ratio at N is systematic-limited at this level.',
 'Soutflow R_Tb 1.3-1.4 (Xb4d) / 0.9 (Xb4b), +-0.25-0.3; N 0.65-0.92 +-0.35; S 0.5-0.6 +-0.15; Bridge unconstrained','R_Tb (dimensionless)','medium',
 's69_q11_wing_check.py -> out/q11/s69_part12_baseA.txt/json (B,C variants alongside)')
add('Is the Xb4d vs Xb4b difference of the Soutflow blue-wing HCN/HCO+ ratio due to missing extended HCN flux? Flux recovery in the blue half and the consequence for p0005 R_wing>R_core',
 'Soutflow, S, N blue half; Xb4b/Xb4d at 1.05"',
 'Xb4b/Xb4d blue-half flux (-400..-100 km/s, r=1", same 1.05" beam): Soutflow HCN 0.61 (0.387/0.630), HCO+ 0.92 (0.429/0.468); S HCN 0.80, HCO+ 0.99; core-window ratios agree (S 0.366 vs 0.360, N 0.733 vs 0.727: 1-2%). The HCN wing at Soutflow therefore has a component with a large-scale (>~2") structure that Xb4b filters and Xb4d keeps; HCO+ does not. Team-a (p0006 Xb4d 1.24 vs Xb4b 1.00) sees the same; our p0005 values (Xb4d 1.40, Xb4b 0.86+-0.25) are reproduced (here -400..-150 window, r=1": Xb4d 1.44, Xb4b 0.85). REVISION of p0005: R_wing>R_core is detected in Xb4d (R 1.3-1.4 vs core 0.5, blue-half HCN 10 sigma) but not demonstrated in Xb4b (0.91 vs core ~0.6, 1 sigma of difference), so it is array/spatial-scale dependent, and any statement about outflow chemistry must carry that: an extended HCN-bright blue skirt (>~2", Xb4d only) cannot be assigned to a compact outflow blob. An imaging artefact specific to Xb4d (clean/sidelobe of the nearby S nucleus, 1.9" away, HCO+ peak 5x higher) cannot be excluded from image products.',
 'HCN blue-half recovery Xb4b/Xb4d 0.61 vs HCO+ 0.92 at Soutflow (+-0.2)','ratio','low','s69_q11_wing_check.py (part 1); numbers from out/q11/s69_part12_baseA.txt')
add('Beam-mixing test of the N wing ratio (team-a p0005-r03/p0010): Xb4b HCN/HCO+ 3-2 at N with the same data at native 0.25", 0.30" and 1.05"',
 'N (HCN peak), apertures r<0.25" and r<0.5"',
 'Wing (both sides stacked, 100-260 km/s about the local centroid) over core (|v_loc|<60), R_wing/R_core: native 0.25" r<0.25": 1.00+-0.14 (R_wing 0.97+-0.13, R_core 0.97+-0.03; HCN 12 sigma, HCO+ 9 sigma); 0.30": 1.05+-0.14 (R_wing 1.01, core 0.97); convolved to 1.05" r<0.5": 1.21+-0.18 (R_wing 0.98, core 0.81); 1.05" r<0.25": 1.41+-0.21 (R_wing 1.14, core 0.81). So no wing rise at 0.25-0.30" (team-a: 1.05+-0.13 vs 0.98), and a 20-40% apparent rise after smoothing to the Xb4d beam (about 1.5-2 sigma each; same data so the errors are correlated). Velocity slope of the ratio per 100 km/s in 40 km/s bins (+-140): -0.044+-0.041 (native), -0.010+-0.036 (0.30"), +0.022+-0.036 (1.05", r<0.5") , +0.055+-0.040 (r<0.25"): the sign change is reproduced but each slope is consistent with zero in our empirical noise (team-a: -0.003+-0.013 -> +0.072+-0.008, smaller errors from null windows). Radial dependence at native 0.25" (annuli 0-0.25/0.25-0.5/0.5-1/1-2"): core R 0.97/0.83/0.66/0.41, wing R (both sides) 0.97+-0.14/1.02+-0.13/0.65+-0.08/0.58: the wing ratio tracks the local core ratio at each radius (wing/core 1.0, 1.2, 1.0, 1.4), i.e. there is no intrinsic velocity dependence of HCN/HCO+ at N at 0.25" resolution; the apparent rise at 1" is the mixing of a wing that is concentrated inside r<0.5" (high-ratio gas) with a core spread to larger radii (ratio 0.4-0.7). Conclusion: team-a p0005-r03/p0010 (i) CONFIRMED qualitatively (beam/radial mixing, no intrinsic wing rise at N); quantitative slope significance not reproduced at their level.',
 'wing/core 1.00+-0.14 (0.25"), 1.05+-0.14 (0.30"), 1.21+-0.18 and 1.41+-0.21 (1.05"); slope changes -0.044 -> +0.022..+0.055 per 100 km/s, each +-0.04','dimensionless','medium',
 's69_q11_wing_check.py (part 2) -> out/q11/s69_part12_baseA.txt (baselines B/C give the same within 0.02)')
add('Is the HCN excess over k*HCO+ at HCN-frame 2375-2575 km/s (-405..-205 km/s about VSYS) at Soutflow a blend? Independent test with the Q0 line list, residual shape, other positions, second array and LTE column needed',
 'Soutflow (S+(-0.2",-1.85")), N, Bridge, S; Xb4d and Xb4b @1.05", r=1"',
 'Reproduced: with k fitted on -205..+95 km/s (k_Tb 0.54), the excess is +0.262+-0.057 Jy km/s (4.6 sigma; 71% of the HCN window flux 0.368) in Xb4d; team-a 0.164 Jy/beam km/s (57%). NOT reproduced in Xb4b: +0.078+-0.103 (0.8 sigma, 36%); the two differ by 1.5 sigma. Other positions (Xb4d): N -0.014+-0.055, Bridge -0.037+-0.047 (Xb4b +0.05+-0.08), S +0.056+-0.046: E/HCN core flux is +0.35 at Soutflow and <~0.01 (3 sigma, N) / <~0.04 at Bridge/S, so a blend that scales with the emission of the dense gas or sits in every nuclear spectrum is excluded; only a species confined to the lobe could do this. Residual spectrum at Soutflow (Xb4d, 50 km/s bins): +0.035 (-425), +0.047, +0.076, +0.061, +0.088 (-225), +0.064 (-175), -0.005 (-125): a continuous skirt of ~300 km/s adjoining the core, 3-5 sigma per bin, with a rising edge toward the core: a single Gaussian fit has centre -150+-40 (bounded at -150), FWHM 430+-70 km/s, whereas the catalogue candidates are narrow lines: HDO 2(2,0)-3(1,3) (266.161 GHz, Eup 157 K, logA -4.76) at -307, CH3CHO 12(6,6)-13(5,8) E (-365, Eup 153 K), l-C3H v4 (-316/-329, Eup 244 K), c-C3H/CH3OH lines are weaker by >1e2 in A; a line with the local dispersion (sigma_HCO+ ~85 km/s, FWHM ~200) would peak at ~-340 and be negligible at -175 where the residual is 3 sigma. Required LTE column (thin, source fills the 2" aperture, E=0.262 Jy km/s = 1.6 K km/s): N(HDO) = 3.4e14 (100 K), 4.6e14 (60 K), 4.4e14 (200 K), 2.2e15 (30 K) cm-2; N(CH3CHO) = 4.5e15 (100 K), 5.8e15 (60 K), 2.6e16 cm-2 (30 K), rotor partition function approximate; this is 250-620 (HDO, 60-200 K) times the thin lower limit N(HCO+) from the HCO+ flux in the same window (1.0e12 cm-2): a lower bound only (HCO+ thick, filling<1 raise both), so an abundance argument cannot exclude HDO without an assumed HDO abundance, which we did not verify. Verdict on p0006 (iii): the excess is not explained by catalogued neighbours of the strength expected for a position-independent blend (absent at N, Bridge, S), and its shape is a broad blue skirt rather than a line; but a lobe-specific HDO/CH3CHO blend is NOT excluded, and the excess itself depends on the array (Xb4d 4.6 sigma, Xb4b 0.8 sigma).',
 'E=0.262+-0.057 Jy km/s (Xb4d, 4.6 sigma); Xb4b 0.078+-0.103; N, Bridge, S consistent with 0 (+-0.05-0.08)','Jy km/s','low',
 's70_q11_blend_nlimit.py -> out/q11/s70.txt/json (catalogue out/linelist.csv)',
 [A('LTE blend model','optically thin, uniform filling of the aperture, T=30-200 K, g_u from the catalogue S mu^2 (HDO 5, CH3CHO 50, i.e. no nuclear-spin weight; partition functions: classical rigid rotor, no spin factor), order-of-magnitude only')])
add('N wing limits (team-a p0006: <2.1% blue 225-350, <3.9% blue 350-750 of core): 3-sigma limits on HCN and HCO+ 3-2 wings at N, Xb4d and Xb4b at 1.05", r=1"',
 'N; windows blue 225-350, blue 350-750, red 350-700 km/s about v_loc',
 'Xb4d: HCN blue 225-350: -0.013+-0.033 Jy km/s, 3 sigma <0.099 = 0.9% of the core (|v|<225) flux 10.6; blue 350-750: <0.19 (1.8%); red 350-700: <0.13 (1.2%). HCO+ (core 14.4): blue 225-350 <0.077 (0.5%); blue 350-750 -0.305+-0.100 (-3.0 sigma, baseline: HCO+ at N has a -1 mJy/beam offset), |limit| 0.30 (2.1%); red <0.085 (0.6%). Xb4b: HCN <1.6%, <2.8%, <1.9%; HCO+ <0.9%, <2.3% (blue 350-750, -2.2 sigma), <1.0%. Conservative single number: no wing above ~2-3% of the core flux at N in either line or array (our random-aperture noise gives limits 2x tighter than team-a, whose windows differ; team-a <2.1/<3.9% is the safer quote given the baseline systematics). Agrees with p0006 (iv) and Michiyama+2018 (undetected N outflow), conditional on the gas being within the 2" aperture.',
 '3-sigma wing/core <0.5-1.8% (225-350 blue), <1.8-2.8% (350-750 blue), <0.6-1.9% (red)','fraction of core flux','medium',
 's70_q11_blend_nlimit.py (part 4) -> out/q11/s70.txt')
add('Does the S deficit of HCN/HCO+ 3-2 (0.38-0.44, team-a p0010) persist at high velocity at S?','S (r=1" aperture, Xb4d/Xb4b @1.05")',
 'Blue half (v_loc-400..-100): 0.61 [0.34,0.80] (Xb4d@1.05"), 0.49 [0.28,0.64] (Xb4d native), 0.49 [0.20,0.74] (Xb4b); red half (+100..+400) 0.45 (HCN 7.6 sigma, HCO+ 8.9 sigma, Xb4d), 0.39 (Xb4b); core 0.366+-0.03. Compared with N core 0.73, N blue 0.65-0.92 and Soutflow 0.9-1.4, S stays at 0.4-0.6 at all velocities where both lines are detected (to |v|~400), with the blue half 1.6 sigma above the core in Xb4d@1.05" only. CONFIRMED (p0010 ii) within 1.5 sigma; the blue-half rise at S seen in Xb4d is not seen at native resolution or in Xb4b.',
 'S wing R_Tb 0.45-0.6 +-0.15 vs core 0.366+-0.03','R_Tb','medium','s69_q11_wing_check.py -> out/q11/s69_part12_baseA.txt')
r['results']=res
r['recipe'].append(dict(order=max(x['order'] for x in r['recipe'])+1,stage='verification',description='Q11: fixed-aperture local-centroid blue-half ratios in Xb4d/Xb4b@1.05" (s69), beam-mixing test at N with Xb4b at 0.25/0.30/1.05" (s69), blend/identity test of the 2375-2575 km/s HCN excess and N wing limits (s70); baselines A/B/C compared',
  software='python3 numpy scipy astropy; s30 loaders',parameters=[A('aperture','r=1.0" (2" diameter)'),A('windows','blue half v_loc-400..-100; wing stack 100-260; core |v_loc|<60-100'),A('baseline','-900<v<-450 median (A), linear (B), v<-800 (C)')],
  scripts=['/workspace/scripts/s69_q11_wing_check.py','/workspace/scripts/s70_q11_blend_nlimit.py','/workspace/scripts/s71_update_report_q11.py']))
r['caveats'].append('Q11: wing ratios at N and Bridge are limited by array/baseline systematics (Xb4b-Xb4d blue-half flux differences 0.15-0.3 Jy km/s at N, HCO+ baseline offset of -1 mJy/beam at N); the Soutflow HCN excess exists in Xb4d (4.6 sigma) but not Xb4b (0.8 sigma): an extended HCN skirt filtered by Xb4b, or an Xb4d imaging artefact, cannot be separated from image products. A lobe-specific HDO/CH3CHO blend is not excluded (needs N(HDO) >= ~3e14 cm-2 at filling 1); distinguishing needs a second HDO/CH3CHO transition (not in band) or CO/other-line association.')
r['interpretation']+=' Q11 (cross-team wing check): at N the HCN/HCO+ 3-2 ratio has no intrinsic velocity dependence at 0.25" (wing/core 1.0+-0.14) and the 20-40% rise at ~1" is beam/radial mixing (team-a p0010 confirmed); S stays at 0.4-0.6 in the wings; the Soutflow blue half has R 1.3-1.4 in Xb4d but 0.9 in Xb4b, so our p0005 "R_wing>R_core robust" is downgraded to array-dependent; N and Bridge do not show a measured blue-half rise; no position-independent blend explains the HCN excess, but a lobe-specific blend is not excluded; N wing <2-3% of the core.'
json.dump(r,open(R,'w'),indent=1)
